import{_ as o,l as s,o as e,c as l,v as t,p as n,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"ECMP 与哈希","description":"","frontmatter":{"title":"ECMP 与哈希","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ecmp-hashing.md","filePath":"cs/ecmp-hashing.md","lastUpdated":1789023840000}'),c={name:"cs/ecmp-hashing.md"};function E(P,a,m,C,_,B){const i=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="ecmp-与哈希" tabindex="-1">ECMP 与哈希 <a class="header-anchor" href="#ecmp-与哈希" aria-label="Permalink to &quot;ECMP 与哈希&quot;">​</a></h1><div class="epigraph"><p>等代价多路径把流用五元组哈希钉到一条下一跳，保序且分流；极化发生在少量大象流撞上同一条边时。</p><footer>—— 据 RFC 2991 / 2992 多路径；RFC 6438 IPv6 流标签实践整理</footer></div><p><a href="/cs/segment-routing">上一课</a> 的前缀 SID 仍走 ECMP。主干 OSPF 已点名等代价。<a href="/cs/lacp">LACP</a> 在二层哈希。缺口是<strong>三层哈希怎么键、为何不保带宽公平</strong>。本课不把 VXLAN 封装写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TE 可以钉路径；默认 IGP 给多条等代价下一跳。逐包喷洒会乱序，TCP 当成丢包。故按流哈希：同四元组（再加流标签）同路径。极化：哈希空间均匀不等于流量均匀——BDP 大的几条流可打满一条 100G，其它边空。重哈希（链路 up/down）会移动流，造成瞬时乱序。</p><p>不要把 ECMP 当成 WFQ：没有按流排队保证。</p><p><span class="marginnote">RFC 2991。数据中心后课 Clos 依赖大量 ECMP。本课不把具体 CRC 多项式当标准。</span></p><h3 id="保序不保公平" tabindex="-1">保序不保公平 <a class="header-anchor" href="#保序不保公平" aria-label="Permalink to &quot;保序不保公平&quot;">​</a></h3><p>按流哈希避免乱序；大象流极化。隧道要把熵透传到外层。重哈希会瞬时乱序。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照 LACP 键与 ECMP 键：一层 vs 三层，对象都是保序分流。画：候选下一跳集合 → 哈希 → 一条。对称性：正向与反向哈希不一致会导致不对称路径，排障痛苦，不是错误。</p>',11)),(e(),n(h,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20EQ%5B%22%E7%AD%89%E4%BB%A3%E4%BB%B7%E4%B8%8B%E4%B8%80%E8%B7%B3%E9%9B%86%22%5D%20--%3E%20H%5B%22%E4%BA%94%E5%85%83%E7%BB%84%E5%93%88%E5%B8%8C%22%5D%0A%20%20H%20--%3E%20ONE%5B%22%E4%B8%80%E6%9D%A1%E8%B7%AF%E5%BE%84%22%5D%0A%20%20EL%5B%22%E5%A4%A7%E8%B1%A1%E6%B5%81%22%5D%20--%3E%20POL%5B%22%E6%9E%81%E5%8C%96%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>MPLS 可用熵标签把内层熵露给外层哈希，避免全网只按外层标签极化。VXLAN 后课同样要把内层端口映到 UDP 源端口。交换机 HOL：多条 ECMP 仍可能在某一跳汇聚到同一出端口。RPKI 与哈希无关。</p><p>随机化种子：不同设备用不同密钥防攻击者构造碰撞打满一条，是安全边注。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入动态负载均衡（packet spraying with reordering repair）的全部。VXLAN 与覆盖网是下一课。后课默认：ECMP = 保序哈希，不保证流量公平。</p><p>不等代价分流（UCMP）按权重，仍是哈希，不是 TE 约束求解。</p><p>上一课留下的缺口在本课收口；「ECMP 与哈希」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/vxlan-overlay">VXLAN 与覆盖网</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>按流哈希保序，按包喷洒乱序。</li><li>极化来自流大小，不是哈希偏置的唯一原因。</li><li>熵要透传到外层才能在隧道上 ECMP。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 2991；RFC 6438。</li></ul>',10))])}const f=o(c,[["render",E]]);export{A as __pageData,f as default};
